<div class="content"><div class="container"><div class="news-index-head"><div><span>PARADISERP</span><h1>Actualités de la ville</h1><p>Retrouve les annonces, nouveautés et informations officielles.</p></div></div><div class="cms-news-grid news-index-grid"><?php if(mysqli_num_rows($NewsRows)):while($n=mysqli_fetch_assoc($NewsRows)):$cover=!empty($n['image_url'])?URL.'/'.$n['image_url']:DY.'/img/backgrounds/bg.jpg';?><article class="cms-news-card"><a class="cms-news-cover" href="<?php echo URL; ?>/article/<?php echo rawurlencode($n['slug']); ?>" style="background-image:url('<?php echo htmlspecialchars($cover,ENT_QUOTES,'UTF-8'); ?>')"><span>ACTUALITÉ</span></a><div class="cms-news-body"><small>Par <?php echo htmlspecialchars($n['author_name']?:'Équipe ParadiseRP',ENT_QUOTES,'UTF-8'); ?> · <?php echo date('d/m/Y',(int)$n['published_at']); ?></small><h3><?php echo htmlspecialchars($n['title'],ENT_QUOTES,'UTF-8'); ?></h3><p><?php echo htmlspecialchars($n['summary'],ENT_QUOTES,'UTF-8'); ?></p><a href="<?php echo URL; ?>/article/<?php echo rawurlencode($n['slug']); ?>">Lire l’article <i class="fas fa-chevron-right"></i></a></div></article><?php endwhile;else:?><div class="cms-news-empty">Aucune actualité publiée.</div><?php endif?></div><nav class="news-pages"><?php if($NewsPage>1):?><a href="?page=<?php echo $NewsPage-1; ?>">← Page précédente</a><?php endif?><span>Page <?php echo $NewsPage; ?></span><?php if(mysqli_num_rows($NewsRows)===9):?><a href="?page=<?php echo $NewsPage+1; ?>">Page suivante →</a><?php endif?></nav></div></div>
